[98319] = {"Asegurar la montaña", {"Encuentra al montaraz Cornelius en El Cubil Pardo, como te ha pedido la montaraz Gretchen."}},
[98321] = {"Envío de Fuegosílex", {"Recoge 8 envíos de Fuegosílex en El Cubil Pardo para Tongus Fuegosílex, que está en Kharanos."}},
[98322] = {"Asegurar la montaña", {"Busca a la montaraz Gretchen al oeste de Kharanos."}},
[98323] = {"Asegurar la montaña", {"Lleva el informe de la montaraz Gretchen a Senir Barbablanca en Kharanos."}},
[98326] = {"Aúllaescarcha", {"Mata a Aúllaescarcha y consigue el saco de pescado para Gretta Ganter, en Las Birras."}},
[98386] = {"El Molino de Alther", {"Mata a 12 tarántulas mayores y destruye 6 huevos de tarántula en el Molino de Alther para el supervisor Olento en Crestagrana."}},
[98387] = {"Bloqueo Roca Negra", {"Llévale 8 armas robadas y 10 suministros de Roca Negra al alguacil Marris en Villa del Lago."}},
[98389] = {"Una luz en la oscuridad", {"Libera a 6 víctimas enredadas en la Hoya Nocturácnidas para Aramis Manomartillo en Camposanto."}},
[98391] = {"La Hermandad de Elune", {"Habla con la hermana Aquinne en Darnassus."}},
[98392] = {"Oscuridad en el claro", {"Consigue el amuleto de Chillaodio, el amuleto de la señora del viento Gaedress y el amuleto de la bruja madre Arysa y entrégaselos a la centinela Arynia Quiebranubes en el Claro del Oráculo."}},
[98398] = {"El Árbol del Oráculo", {"Encuentra la corteza del Árbol del Oráculo cerca para recibir su mensaje."}},
[98403] = {"Odio enraizado", {"Mata a 8 tejemaderas contaminadas y llévale el musgovil maduro de Xethorr el Maldito a Tallonkai Cruzarraíz en Dolanaar."}},
[98407] = {"Demostración de fuerza", {"Consigue 5 colleras con pinchos de los descarnadores de Crestagrana para el ayudante de alguacil Feldon cerca de Villa del Lago."}},
[98423] = {"El tratado de entendimiento", {"Entrega el tratado de entendimiento a Magni Barbabronce en Forjaz."}},
[98424] = {"Las notas de Saltatuercas", {"Reúne el resto de las páginas del supervisor Saltatuercas dentro de la Mina Ventura y Cía. y llévaselas a Morin Acechanubes cerca del Poblado Pezuña de Sangre."}},
[98427] = {"Cese de operaciones", {"Llévale la llave de cortador a Morin Acechanubes, a las afueras del Poblado Pezuña de Sangre."}},
[98430] = {"Los caminantes", {"Ayuda a Perith Pezuña Tempestuosa a escapar de Roca Crines Pálidas e informa de su bienestar a Cairne Pezuña de Sangre, en Cima del Trueno."}},
[98435] = {"Informe de Astatrueno", {"Llévale el informe de Astatrueno al archidruida Hamuul Runatótem en Cima del Trueno."}},
[98461] = {"Amor no correspondido", {"Entrega la nota de Hollee a Tarrel Tejepiedra cerca del Puerto de Menethil, en los Humedales."}},
[98512] = {"Asesinos Al'Aketh", {"Mata 10 asesinos Al'Aketh en las Tierras Altas de Shen'dar."}},
[98545] = {"La carta de Leonid", {"Entrégale la carta lacrada a Glix Xizzix en Entrañas."}},
[98574] = {"Memorándum santificado", {"Lee el memorándum santificado, luego ve a Yunquemar y habla con Silo Khalder."}},
[98581] = {"Runa arcaica", {"Lee la runa arcaica y habla con Teo Mazotormenta en Yunquemar."}},
[98601] = {"Una senda complicada", {"Lee el pergamino consagrado y luego ve a la iglesia de Camposanto y habla con Aramis Manomartillo."}},
[99046] = {"La mensajera perdida", {"Busca a la centinela Eralya Sombra de Hoja en el camino que lleva al Claro del Oráculo."}},
[99047] = {"Aún con vida", {"Pide ayuda a Byancie en Dolanaar para la centinela Eralya Sombra de Hoja."}},
[99048] = {"La Mano desaparecida", {"Busca a Heglan Ojoumbrío al norte del Fuerte de Tiragarde."}},
[99049] = {"La amenaza de las profundidades", {"Busca indicios de lo que ha atacado a Heglan Ojoumbrío."}},
[99050] = {"El Gran Árbol provee", {"Consigue 6 frondas húmedas de azotadora, un vial vacío y agua de manantial refrescante para Byancie en Dolanaar."}},
[99051] = {"La amenaza de las profundidades", {"Consigue 9 aletas espinosas de naga."}},
[99052] = {"La amenaza de las profundidades", {"Mata al gigante de mar en la costa norte de Durotar y vuelve con alguna prueba de tu hazaña."}},
[99053] = {"Fuga de Ban'ethil", {"Ayuda a la centinela Lynessa Florocaso a escapar del Túmulo de Ban'ethil y comunica a la centinela Kyra Cantoestelar, en Dolanaar, que está a salvo."}},
[99073] = {"Aliviar el sufrimiento", {"Lleva el bálsamo hidroazotador a la centinela Eralya Sombra de Hoja en el camino al Árbol del Oráculo."}},
[99079] = {"Caminante Malah", {"Encuentra a la caminante Malah Ventolongo al este del Poblado Pezuña de Sangre, cerca del límite de Mulgore."}},
[99080] = {"Hay que expulsarlos", {"Mata a 6 centauros Galak y 4 avanzados Galak, y llévale la cabeza de Herak el Saqueador a Baine Pezuña de Sangre."}},
[99081] = {"Noticias aciagas", {"Llévale el informe de la caminante Malah a Valiente Corresalvaje en el Poblado Pezuña de Sangre."}},
[99082] = {"El Gran jefe", {"Solicita audiencia con el Gran jefe Cairne Pezuña de Sangre en Cima del Trueno."}},
[99101] = {"Nuestro viejo enemigo", {"Llévale el informe de la caminante Malah a Baine Pezuña de Sangre."}},
[99108] = {"Combate de práctica", {"Derrota a 3 jugadores o guerreros novicios en duelos para Tang Pezuñapétrea."}},
[99123] = {"Perdida en las sombras", {"Ayuda a Pal'juh a escapar del Risco Kolkar y llévale noticias de tu hazaña al maestro Vornal en el Poblado Sen'jin."}},
[99127] = {"Desastre pesquero", {"Comprueba las trampas de pesca en el Lago de Cristal."}},
[99128] = {"Amenaza babosa", {"Mata a 7 múrlocs y a 4 correcorrientes múrloc en el Lago de Cristal y vuelve con Jason Mathers."}},
[99129] = {"Múrloc por liebre", {"Cuéntale el problema de Jason con los múrlocs a Remy \"Dos Veces\"."}},
[99130] = {"Una oferta tentadora", {"Recoge 6 viales de sangre animal y 18 pétalos de floraocaso para usarlos como cebo para múrlocs y vuelve con Remy \"Dos Veces\" en Villadorada."}},
[99131] = {"El cebo del éxito", {"Vuelve con Jason Mathers."}},
[99134] = {"Disciplina", {"Castiga a 5 guardias de la muerte para el ejecutor Zygand."}},
[99141] = {"Paciencia", {"Consigue los informes del guardia de la Muerte Dillinger, el guardia de la Muerte Kristof y Gordo para el ejecutor Zygand."}},
[99142] = {"Tumbalíseas", {"Recoge 5 tumbalíseas y entrégaselas al boticario de segunda Holland."}},
[99143] = {"Botellas y baratijas", {"Consigue 6 trozos de chatarra brillante del campamento múrloc que hay cerca."}},
[99144] = {"En busca de refugio", {"Ayuda a Bareth Piedralba a escapar de la Avanzada de los Cruzados y cuéntale a Shari Fontana en Rémol que está a salvo."}},
[99152] = {"Arriba y abajo", {"Consigue 6 huesos con resplandor tenue para Hilda la Rompedora."}},
[99153] = {"No lo dejes escapar", {"Encuentra el fragmento de cristal oculto bajo Sombravalle para Ephram Barbaro."}},
[99156] = {"Patrulla de la retaguardia", {"Llévale el corazón de Rasgallanto a la guardia de la Muerte Linnea."}},
[99158] = {"El alba en las montañas", {"Llévale el cajón de velas al padre Gavin en el Refugio Pinobruma."}},
[99159] = {"En busca de calor", {"Consigue 14 trozos de leña."}},
[99160] = {"Cólera escarchada", {"Destruye 10 elementales de hielo menores."}},
[99161] = {"Cólera escarchada", {"Mata a Avala y consigue su núcleo."}},
[99162] = {"Frío traicionero", {"Consigue rifles de los montañeros caídos."}},
